import json
n=30
g=[[0]*n for _ in range(n)]
starts=[1,8,15,22,29]
# Interior-color arrangement for the complete 4x4 array of panels.
colors=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
for ri,r0 in enumerate(starts):
  for ci,c0 in enumerate(starts):
    for dr in range(5):
      for dc in range(5):
        r,c=r0+dr,c0+dc
        if r>=n or c>=n: continue
        if dr in (0,4) or dc in (0,4):
          g[r][c]=4
        elif ri<4 and ci<4:
          g[r][c]=colors[ri][ci]
# Connect uncommon interior colors across aligned panels; draw only into zero separator cells.
# For each same-colored sequence in a panel row, bridge from its first to last occurrence,
# on each of the three interior rows. Likewise for columns.
for ri in range(4):
  for color in (3,8):
    inds=[ci for ci in range(4) if colors[ri][ci]==color]
    if len(inds)>=2:
      c_lo=starts[min(inds)]+2 # first inner column
      c_hi=starts[max(inds)]+4 # last inner column
      for r in range(starts[ri]+1,starts[ri]+4):
        for c in range(c_lo,c_hi+1):
          if g[r][c]==0: g[r][c]=color
for ci in range(4):
  for color in (3,8):
    inds=[ri for ri in range(4) if colors[ri][ci]==color]
    if len(inds)>=2:
      r_lo=starts[min(inds)]+2
      r_hi=starts[max(inds)]+4
      for c in range(starts[ci]+1,starts[ci]+4):
        for r in range(r_lo,r_hi+1):
          if g[r][c]==0: g[r][c]=color
print(json.dumps({'action':'submit','grid':g},separators=(',',':')))

